    /**
     * Method to retrieve the Dimension via DimensionFetchOneSummary
     * @param 	summary DimensionFetchOneSummary 
     * @return 	DimensionFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Dimension getDimension( DimensionFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "DimensionFetchOneSummary arg cannot be null" );
    	
    	Dimension entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Dimension
        	// --------------------------------------
        	CompletableFuture<Dimension> futureEntity = queryGateway.query(new FindDimensionQuery( new LoadDimensionFilter( summary.getDimensionId() ) ), ResponseTypes.instanceOf(Dimension.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Dimension with id " + summary.getDimensionId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


